import assert from 'node:assert/strict';
import { makeCounter, retry } from './solution.mjs';

const next = makeCounter(10);
assert.equal(next(), 11);
assert.equal(next(), 12);

let tries = 0;
const val = await retry(async () => {
  tries += 1;
  if (tries < 3) throw new Error('flaky');
  return 'ok';
}, 3);
assert.equal(val, 'ok');
assert.equal(tries, 3);

await assert.rejects(() => retry(async () => { throw new Error('boom'); }, 2), /boom/);
